import{_ as o,o as e,c as a,ag as l}from"./chunks/framework.D64lb950.js";const g=JSON.parse('{"title":"《刻意练习》读书笔记 - 天才不是天生的，是练出来的","description":"","frontmatter":{"title":"《刻意练习》读书笔记 - 天才不是天生的，是练出来的","date":"2026-06-24T00:00:00.000Z","tags":["读书笔记","学习方法","刻意练习","技能成长"],"category":"读书笔记"},"headers":[],"relativePath":"posts/deliberate-practice-review.md","filePath":"posts/deliberate-practice-review.md","lastUpdated":null}'),r={name:"posts/deliberate-practice-review.md"};function n(u,t,s,q,i,d){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="《刻意练习》读书笔记-天才不是天生的-是练出来的" tabindex="-1">《刻意练习》读书笔记 - 天才不是天生的，是练出来的 <a class="header-anchor" href="#《刻意练习》读书笔记-天才不是天生的-是练出来的" aria-label="Permalink to &quot;《刻意练习》读书笔记 - 天才不是天生的，是练出来的&quot;">​</a></h1><p>这本书推翻了我对&quot;天赋&quot;的全部认知。</p><p>安德斯·艾利克森是佛罗里达州立大学的心理学教授，研究&quot;专家&quot;这个话题超过 30 年。他研究的对象包括国际象棋大师、顶级小提琴家、记忆冠军、运动员、医生、飞行员——任何领域里做到最顶尖的那一小撮人。</p><p>他的核心发现就一句话：<strong>天才是练出来的，不是天生的。</strong></p><p>不是&quot;有点道理&quot;那种练，而是有一套非常具体的练法——他称之为 <strong>刻意练习</strong>。普通人练一千小时和高手练一千小时，差别不在于谁的&quot;天赋&quot;更高，而在于<strong>练法完全不同。</strong></p><hr><h2 id="天才的真相-莫扎特不是天生的" tabindex="-1">天才的真相：莫扎特不是天生的 <a class="header-anchor" href="#天才的真相-莫扎特不是天生的" aria-label="Permalink to &quot;天才的真相：莫扎特不是天生的&quot;">​</a></h2><p>莫扎特七岁就能公开演奏小提琴和钢琴，而且具有&quot;绝对音感&quot;——听到任何声音都能立刻说出它是什么音高。这被认为是完美的天才证明。</p><p>但艾利克森翻完历史资料后发现——莫扎特的父亲利奥波德本身就是一位著名的小提琴教师。他写过一本音乐教育教材，在当时影响很大。他在莫扎特出生之前，就已经在系统地训练莫扎特的姐姐。莫扎特三岁开始接受父亲的密集训练——<strong>不是三岁突然展现出天赋，是父亲把一个高效训练体系用在了他身上。</strong></p><p>至于&quot;绝对音感&quot;，后来日本心理学家做了一个实验：招募 24 个普通孩子，用一套专门设计的训练方法教了 18 个月。结果——<strong>24 个孩子全部获得了绝对音感。</strong></p><p>不是天赋。是训练方法。</p><hr><h2 id="一万小时定律错在哪里" tabindex="-1">一万小时定律错在哪里 <a class="header-anchor" href="#一万小时定律错在哪里" aria-label="Permalink to &quot;一万小时定律错在哪里&quot;">​</a></h2><p>马尔科姆·格拉德威尔在《异类》里提出的&quot;一万小时定律&quot;——任何领域投入一万小时就能成为专家——影响极广，但艾利克森说：<strong>它是错的。</strong></p><p>不是时间长短决定了水平高低，是<strong>练习的质量</strong>。</p><p>格拉德威尔的数据来源是艾利克森 1993 年对小提琴家的一项研究。在那个研究里：</p><table tabindex="0"><thead><tr><th style="text-align:left;">组别</th><th style="text-align:left;">累积练习时间（到 20 岁）</th><th style="text-align:left;">水平</th></tr></thead><tbody><tr><td style="text-align:left;">最优秀的学生</td><td style="text-align:left;">约 10000 小时</td><td style="text-align:left;">未来独奏家水准</td></tr><tr><td style="text-align:left;">尚可的学生</td><td style="text-align:left;">约 8000 小时</td><td style="text-align:left;">有潜力的演奏者</td></tr><tr><td style="text-align:left;">一般的学生</td><td style="text-align:left;">约 4000 小时</td><td style="text-align:left;">音乐教师水准</td></tr></tbody></table><p>格拉德威尔取了&quot;一万小时&quot;这个数字，却漏掉了最关键的信息：<strong>不是随便练一万小时。那批最优秀的学生，他们的练习方式和其他人完全不同。</strong></p><p>所以这 5 本书形成了一个完美的闭环：<strong>七个习惯告诉你&quot;要磨刀&quot;，刻意练习告诉你&quot;怎么磨&quot;。</strong></p><hr><h2 id="刻意练习的四个标准" tabindex="-1">刻意练习的四个标准 <a class="header-anchor" href="#刻意练习的四个标准" aria-label="Permalink to &quot;刻意练习的四个标准&quot;">​</a></h2><p>艾利克森总结出了&quot;刻意练习&quot;和&quot;普通练习&quot;之间的四条关键区别：</p><h3 id="_1-有明确目标" tabindex="-1">1. 有明确目标 <a class="header-anchor" href="#_1-有明确目标" aria-label="Permalink to &quot;1. 有明确目标&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">❌ 普通练习的目标</th><th style="text-align:left;">✅ 刻意练习的目标</th></tr></thead><tbody><tr><td style="text-align:left;">练一小时曲子</td><td style="text-align:left;">把第三乐章第 12 小节的那个大跳，连续三次不出错</td></tr><tr><td style="text-align:left;">学一小时英语</td><td style="text-align:left;">听完这段 2 分钟的录音，不看字幕能复述出来</td></tr><tr><td style="text-align:left;">今天写代码</td><td style="text-align:left;">用 vue-composable 模式重构这个页面，同时覆盖率不跌</td></tr></tbody></table><p><strong>普通练习的目标太模糊了。</strong> &quot;练一小时&quot;不是目标，&quot;把某个具体的小技能搞定&quot;才是。模糊目标带来的是低效的&quot;伪练习&quot;——你花了一个小时，但你的注意力根本没集中在要进步的维度上。</p><h3 id="_2-极度专注" tabindex="-1">2. 极度专注 <a class="header-anchor" href="#_2-极度专注" aria-label="Permalink to &quot;2. 极度专注&quot;">​</a></h3><p>这是刻意练习和普通练习最致命的区别。<strong>刻意练习不是享受，它很累，因为它要求你的大脑始终处于&quot;刚好够不着&quot;的边缘。</strong></p><p>小提琴系的学生有一个共同点：他们一天最多有效练习 4-5 小时。不是不想多练，是大脑已经扛不住了。<strong>超过这个时间，练习质量暴跌，继续练反而不如去睡觉。</strong></p><p>而普通练习是什么状态？——放着音乐、刷着手机、做一会歇一会。你确实在&quot;练&quot;，但你的大脑没有被推到极限，所以它不需要改变——<strong>你没有任何进步。</strong></p><h3 id="_3-即时反馈" tabindex="-1">3. 即时反馈 <a class="header-anchor" href="#_3-即时反馈" aria-label="Permalink to &quot;3. 即时反馈&quot;">​</a></h3><blockquote><p>&quot;没有反馈的练习，就是在巩固错误。&quot;</p></blockquote><p>这是全书最扎我的一句话。程序员写代码，跑了能过就觉得自己写对了——但&quot;能过&quot;只是最低标准，不代表写得好。你需要的是<strong>知道哪里可以做得更好</strong>——而且是立刻知道。</p><p>那些音乐学院的顶尖学生，每次练习都有老师在旁边纠正。不是因为老师更聪明，是因为<strong>老师提供了即时反馈</strong>——&quot;这里高了半音&quot;&quot;这里节奏散了&quot;&quot;这里换个指法会更好&quot;——学生当场就能调整。</p><p>普通的练习没有这个。&quot;练了一百遍&quot;但没有人告诉你哪里错了、哪里不够好——你只是在<strong>反复巩固你现有的水平，而不是在突破它。</strong></p><h3 id="_4-走出舒适区" tabindex="-1">4. 走出舒适区 <a class="header-anchor" href="#_4-走出舒适区" aria-label="Permalink to &quot;4. 走出舒适区&quot;">​</a></h3><p>这是四条里最难的一条。<strong>因为大脑天生讨厌&quot;不舒服&quot;。</strong></p><blockquote><p>&quot;如果你觉得某件事很轻松，那你大概率没有在进步。&quot;</p></blockquote><p>艾利克森强调的是&quot;刚好够不着&quot;——不是难到让你崩溃，而是稍微超出你当前的能力边界，需要你拼一把才能做到。在这个区域里，大脑被迫调整自己的神经连接，一点点扩展能力边界。</p><table tabindex="0"><thead><tr><th style="text-align:left;">太简单（舒适区）</th><th style="text-align:left;">刚好够不着（学习区）</th><th style="text-align:left;">太难（恐慌区）</th></tr></thead><tbody><tr><td style="text-align:left;">练已经会的</td><td style="text-align:left;">练刚好不会但努一下能会的</td><td style="text-align:left;">练完全看不懂的</td></tr><tr><td style="text-align:left;">不累</td><td style="text-align:left;">很累，脑力消耗大</td><td style="text-align:left;">崩溃</td></tr><tr><td style="text-align:left;">零进步</td><td style="text-align:left;"><strong>在进步</strong></td><td style="text-align:left;">零进步</td></tr></tbody></table><hr><h2 id="心理表征-高手与普通人的本质差异" tabindex="-1">心理表征：高手与普通人的本质差异 <a class="header-anchor" href="#心理表征-高手与普通人的本质差异" aria-label="Permalink to &quot;心理表征：高手与普通人的本质差异&quot;">​</a></h2><p>这是艾利克森提出的一个关键概念，也是最容易被忽略的部分。</p><p><strong>什么是心理表征？</strong> 就是你对一个事物的&quot;脑子里那幅图&quot;。比如：</p><ul><li>普通人听一首曲子：听到的是&quot;旋律&quot;&quot;节奏&quot;&quot;好不好听&quot;。</li><li>指挥家听同一首曲子：他能听出&quot;第二小提琴声部进晚了 1/4 拍&quot;&quot;圆号在这个段落应该更往下压&quot;&quot;弦乐组和木管组的平衡偏了&quot;。</li><li>普通程序员看一段代码：看到的是&quot;变量命名&quot;&quot;函数调用&quot;&quot;逻辑结构&quot;。</li><li>资深程序员看同一段代码：他能&quot;闻&quot;出设计的问题、预判未来哪里会出 bug、感知到&quot;这里隐藏着一个重构机会&quot;。</li></ul><p><strong>同样的信息进入眼睛和耳朵，但心理表征不同的人&quot;看到&quot;的东西完全不同。心理表征越精细，你在那个领域的判断速度越快、准确度越高、学习效率越惊人。</strong></p><p>而<strong>刻意练习的意义之一，就是不断更新和精细化你的心理表征。</strong> 练习不是让你的手指变得更快——是让你的大脑学会&quot;看到&quot;更多的东西。</p><hr><h2 id="黄金标准-如何找到好导师与好反馈" tabindex="-1">黄金标准：如何找到好导师与好反馈 <a class="header-anchor" href="#黄金标准-如何找到好导师与好反馈" aria-label="Permalink to &quot;黄金标准：如何找到好导师与好反馈&quot;">​</a></h2><p>艾利克森说，刻意练习最理想的状态是有一个好导师。导师的作用就是两件事：<strong>提供即时反馈 + 帮你设计刚好够得着的训练任务。</strong></p><p>如果没有导师怎么办？他给了一些替代方案：</p><p><strong>用工作产出作为反馈</strong>：你写了一段代码，让别人 Code Review——这个 Review 就是反馈。你写完一篇文章，看读者的互动量和留存时间——数据就是反馈。</p><p><strong>用对比作为反馈</strong>：找这个领域里公认做得好的人的作品，拿来跟自己的仔细对比。一句一句、一段一段地找差距。差距就是你要刻意练习的下一个目标。</p><p><strong>用刻意制造挑战作为反馈</strong>：给自己出一个稍微超出当前能力的题目。写代码的——给自己限制时间重写一个模块。学英语的——给自己设一个&quot;听完一段常速新闻并在一分钟内口头总结&quot;的挑战。如果你做不到——说明你卡在哪里了，那个点就是你的下一个练习目标。</p><hr><h2 id="刻意练习在编程与软件开发中的应用" tabindex="-1">刻意练习在编程与软件开发中的应用 <a class="header-anchor" href="#刻意练习在编程与软件开发中的应用" aria-label="Permalink to &quot;刻意练习在编程与软件开发中的应用&quot;">​</a></h2><p>这是我读这本书时最关心的问题：<strong>怎么把刻意练习用到写代码上？</strong></p><p>普通程序员的一天：读需求 → 写代码 → 提交 → 读需求 → 写代码 → 提交。这是&quot;干活&quot;，不是&quot;练习&quot;。干一年，你可能只是在重复同一年的经验，而不是获得了一年的成长。</p><p>刻意练习式编程的几种方式：</p><p><strong>1. 设定技术目标而不是任务目标</strong></p><ul><li>❌ &quot;今天把这个功能写完&quot;（任务目标——做完就行，质量无所谓）</li><li>✅ &quot;今天写这个功能时，要确保每个函数不超过 30 行，测试覆盖率 90% 以上&quot;（技术目标——对质量有明确要求）</li></ul><p><strong>2. 做 Code Kata</strong></p><p>花 30 分钟写一个你已经会的问题，但用一个不熟悉的写法。不是求快，是求&quot;发现新东西&quot;。比如用 TDD 重构一个老模块、用函数式写法重新实现一段逻辑、在一个限制条件（不用 any、不用第三方库）下解决问题。</p><p><strong>3. 主动索要反馈</strong></p><p>写完一段代码，主动问同事：&quot;这个设计你觉得有什么可以改进的地方？&quot;不要等出了问题再改，要在没问题的时候就找优化的空间。</p><p><strong>4. 复盘自己的旧代码</strong></p><p>把你三个月前写的代码翻出来看——<strong>你一定会发现很多&quot;我现在不会这么写&quot;的地方。</strong> 这就是心理表征在进化的证据。但如果你不回头看，你就意识不到自己进步了。意识到进步是继续保持的动力来源。</p><hr><h2 id="为什么大多数人的练习是无效的" tabindex="-1">为什么大多数人的练习是无效的 <a class="header-anchor" href="#为什么大多数人的练习是无效的" aria-label="Permalink to &quot;为什么大多数人的练习是无效的&quot;">​</a></h2><p>艾利克森直言不讳：<strong>绝大多数人练了很多年，其实一直停留在&quot;不会进步&quot;的舒适区。</strong></p><p>这背后的原因有两个：</p><p><strong>一是没有反馈。</strong> 你在苦练，但没人告诉你哪里不对、哪里不够好。你分不清&quot;在进步&quot;和&quot;在重复&quot;的区别。</p><p><strong>二是练错了。</strong> 有些技能你一直在&quot;用&quot;，但从来没有&quot;练&quot;。打字员打了二十年字，速度不如一个练了六个月的速记员——因为打字员是在&quot;使用技能&quot;（停留在舒适区），速记员是在&quot;训练技能&quot;（不断走出舒适区）。</p><p>同样的道理：<strong>你用同一个框架写了三年同样的业务逻辑——这不是三年的经验，这是一年的经验用了三次。</strong> 你不是在成长为更高级的开发者，你只是在成为&quot;更熟练的初级开发者&quot;。</p><hr><h2 id="刻意练习与七个习惯的深度呼应" tabindex="-1">刻意练习与七个习惯的深度呼应 <a class="header-anchor" href="#刻意练习与七个习惯的深度呼应" aria-label="Permalink to &quot;刻意练习与七个习惯的深度呼应&quot;">​</a></h2><p>读完这五本书后我最大的感受是——它们是一个体系。</p><p>刻意练习和七个习惯之间有着明显的呼应：</p><table tabindex="0"><thead><tr><th style="text-align:left;">七个习惯</th><th style="text-align:left;">刻意练习的对应</th></tr></thead><tbody><tr><td style="text-align:left;">习惯一：积极主动</td><td style="text-align:left;">主动走出舒适区，而不是被动地&quot;等到需要再学&quot;</td></tr><tr><td style="text-align:left;">习惯二：以终为始</td><td style="text-align:left;">设定明确的练习目标——不是&quot;练多久&quot;而是&quot;练到什么程度&quot;</td></tr><tr><td style="text-align:left;">习惯三：要事第一</td><td style="text-align:left;">把&quot;刻意练习&quot;放在 Q2 象限——重要但不紧急，但决定了你的长期竞争力</td></tr><tr><td style="text-align:left;">习惯七：不断更新</td><td style="text-align:left;">刻意练习就是&quot;磨刀&quot;的科学方法</td></tr></tbody></table><p>而卡尼曼的系统 2 在这里又出现了——<strong>刻意练习的本质，就是把系统 2 的东西（有意识的、费力的、需要专注的动作）不断重复，逼着大脑重建心理表征，直到那件事变成系统 1 的自动化反应。</strong></p><p>这就是为什么专家能&quot;凭直觉&quot;做出准确的判断——不是因为他天生就有这个直觉，是因为他把判断需要的心理表征练到了<strong>自动化的程度</strong>。</p><hr><h2 id="我的技能突破计划" tabindex="-1">我的技能突破计划 <a class="header-anchor" href="#我的技能突破计划" aria-label="Permalink to &quot;我的技能突破计划&quot;">​</a></h2><p>读完这本书，我做了三个决定：</p><p><strong>1. 用&quot;目标-反馈-调整&quot;代替&quot;随便练练&quot;</strong></p><p>不再做&quot;今天学两小时 XX&quot;这种计划。改成&quot;今天用一个小时，在 XX 限制条件下，搞定 YY 这个具体的技能点。做完之后输出一个可被 review 的产物，找人给反馈。&quot;</p><p><strong>2. 保持一个&quot;学习区项目&quot;</strong></p><p>始终有一个刚好在能力边界上的小项目在进行。不是&quot;大项目&quot;——大项目大部分代码都是舒适区。是小到可以一两天做完、但要用到新东西的项目。做完一个换一个，让&quot;刚好够不着&quot;成为常态。</p><p><strong>3. 建立反馈机制</strong></p><ul><li>代码：定期请同事 Review，不只是 Review 有没有 bug，是 Review 设计、可维护性、命名</li><li>写作：发出去之后看数据——阅读量、留存率、互动——数据不会骗你哪篇文章写得好</li><li>学习：每周日花 15 分钟复盘——这周在哪些技能点上&quot;刻意练习&quot;了？还是只是&quot;用&quot;了旧技能？</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><p>这个系列的其他几篇：</p><ul><li><a href="/my-blog/posts/seven-habits-review">《高效能人士的七个习惯》读书笔记</a> —— 习惯七&quot;不断更新&quot;是刻意练习的上层框架</li><li><a href="/my-blog/posts/thinking-fast-and-slow-review">《思考，快与慢》读书笔记</a> —— 刻意练习如何把系统 2 的技巧变成系统 1 的直觉</li><li><a href="/my-blog/posts/poor-charlies-almanack-review">《穷查理宝典》读书笔记</a> —— 如何用多元思维模型构建你的心理表征</li><li><a href="/my-blog/posts/nonviolent-communication-review">《非暴力沟通》读书笔记</a> —— 每一个沟通技巧，都需要刻意练习来内化</li><li><a href="/my-blog/posts/good-books-recommendation">值得反复阅读的几本好书</a> —— 5 本书的简要速览</li></ul><hr><p><strong>最后记住艾利克森的这句话：</strong></p><blockquote><p>&quot;如果你觉得某件事很轻松，那你大概率没有在进步。&quot;</p></blockquote>',96)])])}const h=o(r,[["render",n]]);export{g as __pageData,h as default};
